INSERT INTO `home_page_settings` (`id`, `meta_title`, `meta_keyword`, `meta_description`, `banner_sec`, `system_setting_sec`, `value_highlight_sec`, `service_heading_section`, `services_sec`, `garage_door`, `quote_sec`, `residential_sec`, `gallery_sec`, `areas_sec`, `faq_sec`, `why_choose_sec`, `blog_sec`, `calltoaction`, `design_sec`, `newgarage`, `testimonial`, `clientlogo`, `form_sec`, `created_by`, `updated_by`, `deleted_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(3, NULL, NULL, NULL, '{\"checked\":1,\"banner_title\":\"Because Your Time is Valuable\",\"banner_subtitle\":\"\",\"banner_description\":\"<p>Independent and impartial Vendor Management Solutions for optimized<br> staffing supplier programs.<\\/p>\",\"banner_img\":\"\",\"mobile_banner_img\":\"\",\"banner_img_1100x480\":\"\",\"banner_formtitle\":\"\",\"button_label\":\"\"}', '{\"checked\":1,\"system_setting_title\":\"Integrated Workforce Management Services Supporting Talent Access, Compliance, and Cost Control\",\"system_sub_title\":\"\",\"system_setting_description\":\"\",\"system_img\":\"\",\"system_img1\":\"\",\"system_img2\":\"\",\"system_img3\":\"\",\"system_img4\":\"\",\"title1\":\"Vendor Management Solutions\",\"title2\":\"Qualified Resources on Demand\",\"title3\":\"Payrolling & Independent Contractor Management\",\"title4\":\"Vendor Management Solutions Advisory\",\"note1\":\"Managing multiple staffing suppliers can create complexity, hidden costs, and compliance risks. TimeMatters simplifies this with a comprehensive, impartial Vendor Management Solution (VMS) designed to give organizations clarity, control, and confidence.\",\"note2\":\"Access vetted, compliant, and skilled contingent resources quickly through Time Matters\\u2019 trusted network of suppliers and contractors.\",\"note3\":\"Simplify payrolling and contractor management with compliant processes, smooth onboarding, and accurate payments across multiple locations and jurisdictions.\",\"note4\":\"Gain independent advisory to build, optimize, and manage vendor programs with better visibility, compliance, performance control, and cost efficiency.\",\"btn_name1\":\"Explore More\",\"btn_name2\":\"Explore More\",\"btn_name3\":\"Explore More\",\"btn_name4\":\"Explore More\",\"btn_url1\":\"https:\\/\\/hamzahk15.sg-host.com\\/service\\/vendor-management-solutions\\/\",\"btn_url2\":\"https:\\/\\/hamzahk15.sg-host.com\\/service\\/the-right-resources-one-call-away\\/\",\"btn_url3\":\"https:\\/\\/hamzahk15.sg-host.com\\/service\\/payrolling-independent-contractor-management\\/\",\"btn_url4\":\"https:\\/\\/hamzahk15.sg-host.com\\/service\\/vendor-management-solution\\/\"}', '{\"checked\":1,\"section_title\":\"Value Highlights\",\"section_description\":\"\",\"items\":[{\"title\":\"Independent & Impartial Expertise\",\"content\":\"As a vendor-agnostic partner (not a staffing firm), we provide objective oversight and unbiased recommendations, free from conflicts of interest.\"},{\"title\":\"Single Point of Contact\",\"content\":\"We streamline communication by acting as your centralized partner across all staffing suppliers, reducing administrative complexity.\"},{\"title\":\"Cost Optimization & Control\",\"content\":\"Through rate standardization, billing accuracy checks, contract compliance, and negotiation support, we deliver measurable cost savings while improving financial discipline.\"},{\"title\":\"Supplier Performance Management\",\"content\":\"We continuously monitor and manage supplier performance to ensure vendors remain accountable and aligned with your business objectives.\"},{\"title\":\"Transparency & Compliance Assurance\",\"content\":\"Our structured processes and ongoing oversight ensure adherence to contracts, rate cards, and labor laws\\u2014minimizing risk and providing peace of mind.\"},{\"title\":\"Data-Driven Insights & Reporting\",\"content\":\"Real-time reporting on vendor performance, spend analysis, and workforce utilization enables informed, strategic decision-making.\"}]}', NULL, NULL, '{\"checked\":1,\"door_title\":\"Common Garage\",\"door_button_name\":\"\",\"door_button_url\":\"\",\"door_sub_title\":\"Door Problems\",\"garage_door_description\":\"<ul>\\r\\n<li>The garage door gets stuck open or closed.<\\/li>\\r\\n<li>The door moves unevenly, and from side to side.<\\/li>\\r\\n<li>You can hear loud noises when opening or closing the garage door.<\\/li>\\r\\n<li>The door falls too quickly when being lowered in manual mode.<\\/li>\\r\\n<li>The remote control door opener fails to work.<\\/li>\\r\\n<\\/ul>\\r\\n<p>If your garage door is suffering from any of these or other problems, give us a call. We will come and assess the problem and work out the best and most cost-effective solution for you.<\\/p>\",\"garage_img\":\"\"}', '{\"checked\":1,\"quote_title\":\"Contact Us Today!\",\"quotesub_title\":\"Our experts are here to help. Contact us today for fast and friendly service.\",\"quote_button_name\":\"Request Help Here\",\"quote_button_url\":\"#getafreequote\",\"quotecall_button_name\":\"CALL NOW\",\"quotecall_button_url\":\"tel:+18004793667\",\"quote_desc\":\"\"}', '{\"checked\":1,\"resi_title\":\"Garage Door Maintenance\",\"resi_sub_title\":\"Garage Door Service & Repair\",\"resi_button_name\":\"CALL NOW\",\"resi_button_url\":\"tel:+18004793667\",\"resi_description\":\"\"}', '{\"checked\":1,\"gallery_title\":\"Our Work\",\"gallery_sub_title\":\"Real feedback from clients who value TimeMatter\\u2019s reliability and transparency.\"}', '{\"checked\":1,\"areas_title\":\"Four Convenient Locations\",\"areas_sub_title\":\"<div class=\\\"area-top-content text-center\\\">\\r\\n<p>At Clark and Sons Garage Doors, we\'re committed to providing timely, reliable service across the entire Delmarva Peninsula. With four conveniently located offices, we\'re always nearby and ready to assist you with expert garage door installations, repairs, and maintenance.<\\/p>\\r\\n<\\/div>\\r\\n<div\\r\\nclass=\\\"area-we-serve-location\\\">\\r\\n<ul class=\\\"two-column-list map-link\\\">\\r\\n <li><b><a href=\\\"https:\\/\\/clarkandsonsdoors.com\\/locations\\/newport-garage-doors\\/\\\"> Newport, Delaware<\\/a><\\/b> \\u2013 Proudly serving Wilmington, Newark, and surrounding communities. <\\/li>\\r\\n <li><b><a href=\\\"https:\\/\\/clarkandsonsdoors.com\\/locations\\/salisbury-garage-doors\\/\\\"> Salisbury, Maryland<\\/a><\\/b> \\u2013 Conveniently located to serve the entire Eastern Shore area.<\\/li>\\r\\n <li><b><a href=\