INSERT INTO `testimonials` (`id`, `name`, `slug`, `email`, `phone`, `sub_content`, `content`, `img`, `is_featured`, `rating`, `review`, `created_by`, `updated_by`, `deleted_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '~ Senior Procurement Manager', 'senior-procurement-manager', '', '', '', '<p>Working with TMi I found them to be extremely professional, very knowledgeable in the industry and direct and honest. They helped to educate me on the vendor’s point of view and overall provided me with more insight into the industry.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-06 11:38:47', '2026-04-11 12:37:17', NULL),
(2, '~ Staffing Operations Head', 'staffing-operations-head', '', '', '', '<p>I would highly recommend using TimeMatters Inc.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-06 12:39:59', '2026-04-11 12:38:24', NULL),
(3, '~ Vendor Management Lead', 'vendor-management-lead', '', '', '', '<p>TMi built an extremely robust auditing program and over a five-year period we were able to return a significant sum (millions of dollars) back into the company’s pocket and improve our Master Services Agreement to cover us in the future.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-06 12:53:52', '2026-04-11 12:39:06', NULL),
(4, '~ Marketing Director', 'marketing-director', '', '', '', '<p>TMi’s level of service was outstanding. Their response time, knowledge and dedication went above and beyond with the Retiree Program and Vendor Management.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-11 12:40:01', '2026-04-15 07:01:03', NULL),
(5, '~ Operations Manager', 'operations-manager', '', '', '', '<p>Superb service and expertise. The fact that they are independent and not a staffing firm provided an impartial, objective position to our Vendor Management and Audit services.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-11 12:40:46', '2026-04-15 07:01:15', NULL),
(6, '~ Business Development Manager', 'business-development-manager', '', '', '', '<p>Bringing back previous employees through TMi removed the risk and administrative headaches.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-11 12:41:24', '2026-04-15 07:01:26', NULL),
(7, '~ Digital Marketing Manager', 'digital-marketing-manager', '', '', '', '<p>TimeMatters helped us access better talent more quickly through their network of suppliers. Their independence added clarity and stability to our vendor program.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-11 12:42:50', '2026-04-15 07:01:36', NULL),
(8, '~ Supply Chain Manager', 'supply-chain-manager', '', '', '', '<p>Centralizing vendor oversight with TimeMatters reduced delays, improved payment accuracy, and made our hiring cycle far more consistent and predictable.</p>', NULL, '1', '5', '1', 20, 20, NULL, '2026-04-11 12:43:19', '2026-04-15 07:01:46', NULL);

