(44, 'home-page-settings', '3', '{\"id\":3,\"meta_title\":null,\"meta_keyword\":null,\"meta_description\":null,\"banner_sec\":\"{\\\"checked\\\":1,\\\"banner_title\\\":\\\"Because Your Time is Valuable\\\",\\\"banner_subtitle\\\":\\\"\\\",\\\"banner_description\\\":\\\"<p>Independent and impartial Vendor Management Solutions for optimized<br> staffing supplier programs.<\\\\\\/p>\\\",\\\"banner_img\\\":\\\"\\\",\\\"mobile_banner_img\\\":\\\"\\\",\\\"banner_img_1100x480\\\":\\\"\\\",\\\"banner_formtitle\\\":\\\"\\\",\\\"button_label\\\":\\\"\\\"}\",\"system_setting_sec\":\"{\\\"checked\\\":1,\\\"system_setting_title\\\":\\\"Integrated Workforce Management Services Supporting Talent Access, Compliance, and Cost Control\\\",\\\"system_sub_title\\\":\\\"\\\",\\\"system_setting_description\\\":\\\"\\\",\\\"system_img\\\":\\\"\\\",\\\"system_img1\\\":\\\"\\\",\\\"system_img2\\\":\\\"\\\",\\\"system_img3\\\":\\\"\\\",\\\"system_img4\\\":\\\"\\\",\\\"title1\\\":\\\"Vendor Management Solutions\\\",\\\"title2\\\":\\\"Qualified Resources on Demand\\\",\\\"title3\\\":\\\"Payrolling & Independent Contractor Management\\\",\\\"title4\\\":\\\"Vendor Management Solutions Advisory\\\",\\\"note1\\\":\\\"Managing multiple staffing suppliers can create complexity, hidden costs, and compliance risks. TimeMatters simplifies this with a comprehensive, impartial Vendor Management Solution (VMS) designed to give organizations clarity, control, and confidence.\\\",\\\"note2\\\":\\\"Custom, mobile-first websites exceeding Core Web Vitals, structured for AI-readiness with semantic HTML and schema markup.\\\",\\\"note3\\\":\\\"SEO-optimized website copy and AI-citation content created through our signature content interview process. No writing skills required from clients.\\\",\\\"note4\\\":\\\"SEO-optimized website copy and AI-citation content created through our signature content interview process. No writing skills required from clients.\\\",\\\"btn_name1\\\":\\\"Explore More\\\",\\\"btn_name2\\\":\\\"Explore More\\\",\\\"btn_name3\\\":\\\"Explore More\\\",\\\"btn_name4\\\":\\\"Explore More\\\",\\\"btn_url1\\\":\\\"\\\",\\\"btn_url2\\\":\\\"\\\",\\\"btn_url3\\\":\\\"\\\",\\\"btn_url4\\\":\\\"\\\"}\",\"value_highlight_sec\":\"{\\\"checked\\\":1,\\\"section_title\\\":\\\"Value Highlights\\\",\\\"section_description\\\":\\\"\\\",\\\"items\\\":[{\\\"title\\\":\\\"Independent & Impartial Expertise\\\",\\\"content\\\":\\\"As a vendor-agnostic partner (not a staffing firm), we provide objective oversight and unbiased recommendations, free from conflicts of interest.\\\"},{\\\"title\\\":\\\"Single Point of Contact\\\",\\\"content\\\":\\\"We streamline communication by acting as your centralized partner across all staffing suppliers, reducing administrative complexity.\\\"},{\\\"title\\\":\\\"Cost Optimization & Control\\\",\\\"content\\\":\\\"Through rate standardization, billing accuracy checks, contract compliance, and negotiation support, we deliver measurable cost savings while improving financial discipline.\\\"},{\\\"title\\\":\\\"Supplier Performance Management\\\",\\\"content\\\":\\\"We continuously monitor and manage supplier performance to ensure vendors remain accountable and aligned with your business objectives.\\\"},{\\\"title\\\":\\\"Transparency & Compliance Assurance\\\",\\\"content\\\":\\\"Our structured processes and ongoing oversight ensure adherence to contracts, rate cards, and labor laws\\\\u2014minimizing risk and providing peace of mind.\\\"},{\\\"title\\\":\\\"Data-Driven Insights & Reporting\\\",\\\"content\\\":\\\"Real-time reporting on vendor performance, spend analysis, and workforce utilization enables informed, strategic decision-making.\\\"}]}\",\"service_heading_section\":null,\"services_sec\":null,\"garage_door\":\"{\\\"checked\\\":1,\\\"door_title\\\":\\\"Common Garage\\\",\\\"door_button_name\\\":\\\"\\\",\\\"door_button_url\\\":\\\"\\\",\\\"door_sub_title\\\":\\\"Door Problems\\\",\\\"garage_door_description\\\":\\\"<ul>\\\\r\\\\n<li>The garage door gets stuck open or closed.<\\\\\\/li>\\\\r\\\\n<li>The door moves unevenly, and from side to side.<\\\\\\/li>\\\\r\\\\n<li>You can hear loud noises when opening or closing the garage door.<\\\\\\/li>\\\\r\\\\n<li>The door falls too quickly when being lowered in manual mode.<\\\\\\/li>\\\\r\\\\n<li>The remote control door opener fails to work.<\\\\\\/li>\\\\r\\\\n<\\\\\\/ul>\\\\r\\\\n<p>If your garage door is suffering from any of these or other problems, give us a call. We will come and assess the problem and work out the best and most cost-effective solution for you.<\\\\\\/p>\\\",\\\"garage_img\\\":\\\"\\\"}\",\"quote_sec\":\"{\\\"checked\\\":1,\\\"quote_title\\\":\\\"Contact Us Today!\\\",\\\"quotesub_title\\\":\\\"Our experts are here to help. Contact us today for fast and friendly service.\\\",\\\"quote_button_name\\\":\\\"Request Help Here\\\",\\\"quote_button_url\\\":\\\"#getafreequote\\\",\\\"quotecall_button_name\\\":\\\"CALL NOW\\\",\\\"quotecall_button_url\\\":\\\"tel:+18004793667\\\",\\\"quote_desc\\\":\\\"\\\"}\",\"residential_sec\":\"{\\\"checked\\\":1,\\\"resi_title\\\":\\\"Garage Door Maintenance\\\",\\\"resi_sub_title\\\":\\\"Garage Door Service & Repair\\\",\\\"resi_button_name\\\":\\\"CALL NOW\\\",\\\"resi_button_url\\\":\\\"tel:+18004793667\\\",\\\"resi_description\\\":\\\"\\\"}\",\"gallery_sec\":\"{\\\"checked\\\":1,\\\"gallery_title\\\":\\\"Our Work\\\",\\\"gallery_sub_title\\\":\\\"Real feedback from clients who value TimeMatter\\\\u2019s reliability and transparency.\\\"}\",\"areas_sec\":\"{\\\"checked\\\":1,\\\"areas_title\\\":\\\"Four Convenient Locations\\\",\\\"areas_sub_title\\\":\\\"<div class=\\\\\\\"area-top-content text-center\\\\\\\">\\\\r\\\\n<p>At Clark and Sons Garage Doors, we\'re committed to providing timely, reliable service across the entire Delmarva Peninsula. With four conveniently located offices, we\'re always nearby and ready to assist you with expert garage door installations, repairs, and maintenance.<\\\\\\/p>\\\\r\\\\n<\\\\\\/div>\\\\r\\\\n<div\\\\r\\\\nclass=\\\\\\\"area-we-serve-location\\\\\\\">\\\\r\\\\n<ul class=\\\\\\\"two-column-list map-link\\\\\\\">\\\\r\\\\n <li><b><a href=\\\\\\\"https:\\\\\\/\\\\\\/clarkandsonsdoors.com\\\\\\/locations\\\\\\/newport-garage-doors\\\\\\/\\\\\\\"> Newport, Delaware<\\\\\\/a><\\\\\\/b> \\\\u2013 Proudly serving Wilmington, Newark, and surrounding communities. <\\\\\\/li>\\\\r\\\\n <li><b><a href=\\\\\\\"https:\\\\\\/\\\\\\/clarkandsonsdoors.com\\\\\\/locations\\\\\\/salisbury-garage-doors\\\\\\/\\\\\\\"> Salisbury, Maryland<\\\\\\/a><\\\\\\/b> \\\\u2013 Conveniently located to serve the entire Eastern Shore area.<\\\\\\/li>\\\\r\\\\n <li><b><a href=\\\\\\\"https:\\\\\\/\\\\\\/clarkandsonsdoors.com\\\\\\/locations\\\\\\/dover-garage-doors\\\\\\/\\\\\\\"> Dover, Delaware<\\\\\\/a><\\\\\\/b> \\\\u2013 Centrally positioned to promptly assist homeowners and businesses throughout central Delaware.<\\\\\\/li>\\\\r\\\\n <li><b><a href=\\\\\\\"https:\\\\\\/\\\\\\/clarkandsonsdoors.com\\\\\\/locations\\\\\\/georgetown-garage-doors\\\\\\/\\\\\\\"> Georgetown, Delaware<\\\\\\/a><\\\\\\/b> \\\\u2013 Dedicated to providing dependable garage door solutions across southern Delaware and coastal communities.<\\\\\\/li>\\\\r\\\\n\\\\r\\\\n\\\\r\\\\n<\\\\\\/ul>\\\\r\\\\n<\\\\\\/div>\\\",\\\"areas_button_name\\\":\\\"\\\",\\\"areas_button_url\\\":\\\"\\\",\\\"areas_img\\\":\\\"\\\"}\",\"faq_sec\":\"{\\\"checked\\\":1,\\\"faq_title\\\":\\\"FAQ\'s\\\",\\\"faq_sub_title\\\":\\\"\\\",\\\"faq_img\\\":\\\"\\\"}\",\"why_choose_sec\":\"{\\\"checked\\\":1,\\\"why_choose_title\\\":\\\"Why Choose TimeMatters\\\",\\\"why_choose_sub_title\\\":\\\"\\\",\\\"why_choose_img\\\":\\\"\\\",\\\"why_choose_img1\\\":\\\"2929\\\",\\\"why_choose_img2\\\":\\\"\\\",\\\"why_choose_img3\\\":\\\"\\\",\\\"why_choose_img4\\\":\\\"\\\",\\\"why_choose_img5\\\":\\\"\\\",\\\"why_choose_img6\\\":\\\"\\\",\\\"why_choose_title1\\\":\\\"Independent & Vendor-Neutral\\\",\\\"why_choose_title2\\\":\\\"Simplified Supplier Oversight\\\",\\\"why_choose_title3\\\":\\\"Cost Control & Efficiency\\\",\\\"why_choose_title4\\\":\\\"Accountability & Transparency\\\",\\\"why_choose_title5\\\":\\\"Proven Experience\\\",\\\"why_choose_title6\\\":\\\"\\\",\\\"why_choose_description1\\\":\\\"100% impartial, no ties to staffing suppliers.\\\",\\\"why_choose_description2\\\":\\\"One point of contact across all staffing vendors.\\\",\\\"why_choose_description3\\\":\\\"Rate standardization, compliance, and spend optimization.\\\",\\\"why_choose_description4\\\":\\\"Performance scorecards and real-time reporting for clear vendor evaluation.\\\",\\\"why_choose_description5\\\":\\\"Decades of expertise helping organizations manage complex supplier networks.\\\",\\\"why_choose_description6\\\":\\\"\\\"}\",\"blog_sec\":\"{\\\"checked\\\":1,\\\"blog_title\\\":\\\"Recent Blogs\\\"}\",\"calltoaction\":\"{\\\"checked\\\":1,\\\"calltoaction_title\\\":\\\"Don\'t Try to Fix it Yourself!\\\",\\\"calltosub_title\\\":\\\"\\\",\\\"button_name\\\":\\\"GET A QUOTE\\\",\\\"button_url\\\":\\\"#getafreequote\\\",\\\"call_button_name\\\":\\\"CALL NOW\\\",\\\"call_button_url\\\":\\\"tel:+18004793667\\\",\\\"call_button_desc\\\":\\\"It\'s crucial to entrust the repair of faulty garage doors to a skilled technician. Issues with cables or springs can pose significant hazards without proper expertise. With our extensive experience and specialized equipment, rest assured that all problems will be safely resolved.\\\"}\",\"design_sec\":\"{\\\"checked\\\":1,\\\"design_title\\\":\\\"Design Center\\\",\\\"button_name\\\":\\\"DESIGN NOW!\\\",\\\"button_url\\\":\\\"https:\\\\\\/\\\\\\/raynor.chameleonpower.com\\\\\\/?dealer=true&did=0027\\\",\\\"design_sub_title\\\":\\\"Customize your garage door!\\\",\\\"design_description\\\":\\\"<p>Build the garage door of your dreams with our design center. Quickly scroll through our wide range of models, styles, and options, and request a quote in a matter of minutes.<\\\\\\/p>\\\",\\\"design_img\\\":\\\"\\\"}\",\"newgarage\":\"{\\\"checked\\\":1,\\\"newgarage_title\\\":\\\"Need a New Garage Door?\\\",\\\"newgarage_desc\\\":\\\"\\\"}\",\"testimonial\":\"{\\\"checked\\\":1,\\\"testimonial_title\\\":\\\"Ready to Take Control of Your Vendor Relationships?\\\",\\\"testimonial_sub_title\\\":\\\"Discover how TimeMatters can streamline your staffing supplier management, optimize costs, and ensure compliance across your workforce program.\\\"}\",\"clientlogo\":\"{\\\"checked\\\":1,\\\"clientlogo_title\\\":\\\"\\\"}\",\"form_sec\":\"{\\\"checked\\\":1,\\\"form_title\\\":\\\"Ready to Take Control of Your Vendor Relationships?\\\",\\\"form_sub_title\\\":\\\"\\\",\\\"form_short_desc\\\":\\\"<p>Discover how TimeMatters can streamline your staffing supplier management, optimize costs, and ensure compliance across your workforce program.<\\\\\\/p>\\\",\\\"form_btn_name\\\":\\\"Schedule a Free Consultation\\\",\\\"form_btn_url\\\":\\\"\\\"}\",\"created_by\":null,\"updated_by\":\"20\",\"deleted_by\":null,\"created_at\":null,\"updated_at\":\"2026-04-09T02:36:15.000000Z\",\"deleted_at\":null}', 20, 20, '2026-04-10 06:49:06', '2026-04-10 06:49:06', NULL);
