(57, 'abouts', '1', '{\"id\":1,\"meta_title\":null,\"meta_keyword\":null,\"meta_description\":null,\"title\":\"About Us\",\"description\":\"<p>We build solutions that create value and drive success.<\\/p>\",\"bannerimage\":null,\"abt_mb_bannerimage\":null,\"mobile_banner_image\":null,\"mission_values\":\"{\\\"status\\\":1,\\\"mv_post_1\\\":\\\"Managing Partner & CEO\\\",\\\"mv_post_2\\\":\\\"Chief Financial Officer (CFO)\\\",\\\"mv_title_1\\\":\\\"Brian Keyes\\\",\\\"mv_title_2\\\":\\\"Joanne Irons\\\",\\\"mv_title_3\\\":\\\"\\\",\\\"mv_title_4\\\":\\\"\\\",\\\"mv_title_5\\\":\\\"\\\",\\\"mv_title_6\\\":\\\"\\\",\\\"mv_description_1\\\":\\\"<p>Brian leads TimeMatters Inc. with a focus on impartiality, efficiency, and measurable results. With deep experience in vendor governance, he ensures that organizations gain control over their staffing supplier programs while reducing complexity and costs.<\\\\\\/p>\\\",\\\"mv_description_2\\\":\\\"<p>Joanne brings financial rigor and strategic insight to TimeMatters Inc. She oversees compliance, cost optimization, and fiscal transparency, ensuring our clients achieve maximum return on investment from vendor partnerships.<\\\\\\/p>\\\",\\\"mv_description_3\\\":\\\"\\\",\\\"mv_description_4\\\":\\\"\\\",\\\"mv_description_5\\\":\\\"\\\",\\\"mv_description_6\\\":\\\"\\\",\\\"mv_icon_1\\\":\\\"\\\",\\\"mv_icon_2\\\":\\\"\\\",\\\"mv_icon_3\\\":\\\"\\\",\\\"mv_icon_4\\\":\\\"\\\",\\\"mv_icon_5\\\":\\\"\\\",\\\"mv_icon_6\\\":\\\"\\\"}\",\"missiontitle\":\"Who We Are\",\"missiondescription\":\"<p>At <b>TimeMatters Inc.<\\/b>, we believe your time is too valuable to be lost in the complexity of managing multiple staffing vendors. That\\u2019s why we specialize exclusively in <b>independent, impartial Vendor Management Solutions (VMS)<\\/b>.<\\/p>\\r\\n<p>Unlike staffing agencies, we have no vested interest in supplier placement. Our role is to ensure that your vendor ecosystem operates with <b>transparency, accountability, and cost efficiency.<\\/b><\\/p>\\r\\n<p>For over two decades, we have partnered with organizations to help them reduce risk, optimize costs, and gain visibility into their contingent workforce programs.,\\/p&gt;<\\/p>\",\"missionbutton\":null,\"missionbuttonurl\":null,\"teamtitle\":null,\"teamdescription\":null,\"teambackground\":null,\"button1\":null,\"button1url\":null,\"button2\":null,\"button2url\":null,\"historytitle\":null,\"historysubtitle\":\"Culture & Values\",\"historydescription\":\"<p>At the core of TimeMatters Inc. is a commitment to integrity, independence, and client success.<\\/p>\",\"historyimage\":null,\"historybutton\":null,\"historybuttonurl\":null,\"our_history_title\":\"Our Specialists\",\"our_history_desc\":\"<p> Behind every client success is a dedicated team of professionals who ensure smooth delivery and support:<\\/p>\",\"how_we_deliver_title\":\"How We Deliver\",\"how_we_deliver_desc\":\"<p> We combine industry expertise, disciplined processes, and data-driven insights to deliver value to every client engagement.<\\/p>\",\"hwd_img_note\":\"Our culture is built on trust, professionalism, and a passion for helping organizations reclaim control of their vendor relationships.\",\"hwd_subtitle_1\":\"Neutral & Impartial\",\"hwd_note_1\":\"As a vendor-agnostic partner, we provide unbiased recommendations that serve only your organization\\u2019s best interests.\",\"hwd_subtitle_2\":\"Structured Oversight\",\"hwd_note_2\":\"Through compliance reviews, and standardized processes, we keep your staffing vendors aligned and accountable.\",\"hwd_subtitle_3\":\"Proven Results\",\"hwd_note_3\":\"Our clients consistently report reduced costs, improved compliance, and simplified vendor relationships.\",\"hwd_subtitle_4\":\"Dedicated Support\",\"hwd_note_4\":\"From financial oversight to administrative guidance, our team ensures you have the resources to succeed.\",\"cv_img_note\":\"Our culture is built on trust, professionalism, and a passion for helping organizations reclaim control of their vendor relationships.\",\"cv_subtitle_1\":\"Integrity First\",\"cv_note_1\":\"We are guided by honesty and transparency in every engagement.\",\"cv_subtitle_2\":\"Independence Matters\",\"cv_note_2\":\"Our impartial stance ensures our advice and oversight remain free of vendor influence.\",\"cv_subtitle_3\":\"Collaboration\",\"cv_note_3\":\"We partner closely with our clients, working as an extension of their team.\",\"cv_subtitle_4\":\"Excellence\",\"cv_note_4\":\"We hold ourselves to the highest standards in service delivery, ensuring measurable results.\",\"cv_subtitle_5\":\"Accountability\",\"cv_note_5\":\"Just as we hold your vendors accountable, we hold ourselves accountable to deliver value and impact.\",\"el_title\":\"Executive Leadership\",\"os_subtitle_1\":\"Consultant Accounts Managers\",\"os_note_1\":\"Builds strong client relationships and ensures seamless vendor management processes.\",\"os_subtitle_2\":\"Financial Service Managers\",\"os_note_2\":\"Oversee financial compliance, billing accuracy, and vendor cost optimization.\",\"os_subtitle_3\":\"Administrative Support\",\"os_note_3\":\"Provides critical organizational and operational assistance to keep client programs running efficiently.\",\"why_title\":\"Why TimeMatters\",\"why_desc\":\"<p> At TimeMatters Inc., we are more than consultants \\u2014 we are your partner in vendor governance. Our impartial, independent approach ensures you gain clarity, control, and confidence over your staffing supplier programs.<\\/p>\\r\\n<p><b>Because your time is valuable - we\\u2019re here to listen, guide, and simplify vendor management together<\\/b><\\/p>\",\"why_button_name\":\"Connect with Us\",\"why_button_url\":null,\"created_by\":5,\"updated_by\":20,\"deleted_by\":null,\"created_at\":\"2024-07-04T12:49:25.000000Z\",\"updated_at\":\"2026-04-11T02:10:41.000000Z\",\"deleted_at\":null}', 20, 20, '2026-04-11 08:10:02', '2026-04-11 08:10:02', NULL),
(58, 'testimonials', '1', '{\"id\":1,\"name\":\"~ Senior Procurement Manager\",\"slug\":\"senior-procurement-manager\",\"email\":\"\",\"phone\":\"\",\"sub_content\":\"\",\"content\":\"<p>\\r\\nSuperb service and expertise. The fact that they are independent of any staffing agency\\r\\n                            provided\\r\\n                            us with an impartial, objective position that was invaluable.<\\/p>\",\"img\":null,\"is_featured\":\"1\",\"rating\":null,\"review\":\"0\",\"created_by\":20,\"updated_by\":20,\"deleted_by\":null,\"created_at\":\"2026\\/04\\/06\",\"updated_at\":\"2026\\/04\\/09\",\"deleted_at\":null}', 20, 20, '2026-04-11 12:37:17', '2026-04-11 12:37:17', NULL),
(59, 'testimonials', '2', '{\"id\":2,\"name\":\"~ Staffing Operations Head\",\"slug\":\"staffing-operations-head\",\"email\":\"\",\"phone\":\"\",\"sub_content\":\"\",\"content\":\"<p>TimeMatters helped us streamline vendor performance management and gave us visibility into true staffing costs. Their neutrality made all the difference.<\\/p>\",\"img\":null,\"is_featured\":\"1\",\"rating\":null,\"review\":\"0\",\"created_by\":20,\"updated_by\":20,\"deleted_by\":null,\"created_at\":\"2026\\/04\\/06\",\"updated_at\":\"2026\\/04\\/06\",\"deleted_at\":null}', 20, 20, '2026-04-11 12:38:24', '2026-04-11 12:38:24', NULL),
(60, 'testimonials', '3', '{\"id\":3,\"name\":\"~ Vendor Management Lead\",\"slug\":\"vendor-management-lead\",\"email\":\"\",\"phone\":\"\",\"sub_content\":\"\",\"content\":\"<p>Working with TimeMatters improved our transparency and efficiency. Their independent insights\\r\\n                          helped optimize vendor performance and control resource allocation.<\\/p>\",\"img\":null,\"is_featured\":\"1\",\"rating\":null,\"review\":\"0\",\"created_by\":20,\"updated_by\":20,\"deleted_by\":null,\"created_at\":\"2026\\/04\\/06\",\"updated_at\":\"2026\\/04\\/06\",\"deleted_at\":null}', 20, 20, '2026-04-11 12:39:06', '2026-04-11 12:39:06', NULL),
