anges to the Privacy Policy\\r\\n<\\/h2>\\r\\n<p>\\r\\nWe may update this Privacy Policy from time to time to reflect changes in our practices or legal obligations. We encourage you to review this policy periodically for any updates. Your continued use of our website and services after any modifications to the policy will constitute your acknowledgment and acceptance of the changes.\\r\\n<\\/p>\\r\\n<h2>\\r\\n  Contact Us\\r\\n<\\/h2>\\r\\n<p>\\r\\nIf you have any questions, comments, or concerns about this Privacy Policy or our privacy practices, please contact us at:\\r\\n<\\/p>\\r\\n<h4 class=\\\"inc\\\">\\r\\n  TimeMatters Inc.\\r\\n<\\/h4>\\r\\n<p>\\r\\nAddress: 200 Consumers Rd #809\\r\\n<br>\\r\\n  North York, ON M2J 4R4\\r\\n<\\/p>\\r\\n<p>\\r\\nEmail:\\r\\n<a class=\\\"txt\\\" href=\\\"mailto:privacy@timemattersinc.com\\\">\\r\\n  privacy@timemattersinc.com\\r\\n<\\/a>\\r\\n<\\/p>\\r\\n<p>\\r\\nPhone:\\r\\n<a class=\\\"txt\\\" href=\\\"tel:+905-863-3993 \\\">\\r\\n  905-863-3993\\r\\n<\\/a>\\r\\n<\\/p>\\r\\n<\\/div>\",\"published_at\":\"2026-04-15 06:09:34\",\"author\":\"20\",\"image\":null,\"visibility\":\"Public\",\"password\":null,\"publish_status\":\"Published\",\"make_with_builder\":\"0\",\"page_slider\":\"0\",\"page_attribute\":null,\"page_template\":\"0\",\"header_banner\":\"0\",\"header_banner_img\":null,\"header_banner_title\":null,\"header_banner_subtitle\":null,\"meta_title\":null,\"meta_keyword\":null,\"meta_description\":null,\"page_index\":\"on\",\"canonical_url\":null,\"created_by\":20,\"updated_by\":20,\"deleted_by\":null,\"created_at\":\"2026\\/04\\/15\",\"updated_at\":\"2026\\/04\\/15\",\"deleted_at\":null}', 20, 20, '2026-04-15 06:15:30', '2026-04-15 06:15:30', NULL),
