(100, 'testimonials', '7', '{\"id\":7,\"name\":\"content vendor mng sol\",\"slug\":\"content-vendor-mng-sol\",\"email\":\"\",\"phone\":\"\",\"sub_content\":\"\",\"content\":\"<p>TimeMatters helped us access better talent more quickly through their network of suppliers. Their independence added clarity and stability to our vendor program.<\\/p>\",\"img\":null,\"is_featured\":\"1\",\"rating\":\"5\",\"review\":\"1\",\"created_by\":20,\"updated_by\":20,\"deleted_by\":null,\"created_at\":\"2026\\/04\\/11\",\"updated_at\":\"2026\\/04\\/11\",\"deleted_at\":null}', 20, 20, '2026-04-15 06:59:22', '2026-04-15 06:59:22', NULL),
